    flags[#flags + 1] = "Order Execution Return Bitfield 22 Cmc Sessions"
  end
  -- Is Order Execution Return Bitfield 22 Intra Firm Trade Ind flag set?
  if bit.band(value, 0x10) ~= 0 then
    flags[#flags + 1] = "Order Execution Return Bitfield 22 Intra Firm Trade Ind"
  end
  -- Is Order Execution Return Bitfield 22 Cmc Match Qty flag set?
  if bit.band(value, 0x20) ~= 0 then
    flags[#flags + 1] = "Order Execution Return Bitfield 22 Cmc Match Qty"
  end
  -- Is Order Execution Return Bitfield 22 Step Up Amount flag set?
  if bit.band(value, 0x40) ~= 0 then
    flags[#flags + 1] = "Order Execution Return Bitfield 22 Step Up Amount"
  end
  -- Is Order Execution Return Bitfield 22 Reserved 128 flag set?
  if bit.band(value, 0x80) ~= 0 then
    flags[#flags + 1] = "Order Execution Return Bitfield 22 Reserved 128"
  end

  return table.concat(flags, "|")
