  -- Number Of Return Bitfields: Binary
  index, number_of_return_bitfields = cboe_bzxequities_binaryorderentry_boe_v2_4_57.number_of_return_bitfields.dissect(buffer, index, packet, parent)

  -- Runtime optional field: Order Modified Return Bitfield 1
  local order_modified_return_bitfield_1 = nil

  local order_modified_return_bitfield_1_exists = number_of_return_bitfields >= 1

  if order_modified_return_bitfield_1_exists then

    -- Order Modified Return Bitfield 1: Struct of 8 fields
    index, order_modified_return_bitfield_1 = cboe_bzxequities_binaryorderentry_boe_v2_4_57.order_modified_return_bitfield_1.dissect(buffer, index, packet, parent)
